    pad_wide: { osc: [{ w: 'sawtooth', det: -12 }, { w: 'sawtooth', det: 12 }], f: { cut: 1500, env: 900, a: 0.6, dec: 1.2, q: 0.9 }, a: 0.5, d: 1, s: 0.85, r: 0.9, gain: 0.14 },
