  function metaStat(st, key, def) {
    const v = st && st.metaStats ? st.metaStats[key] : undefined;
    return typeof v === 'number' && isFinite(v) && v > 0 ? v : def;
  }
  const punchOf = (st) => metaStat(st, 'power', null);
  function streakTime() {
    const H = KK.Battle && KK.Battle.Hero;
    const w = H ? H.COMBO_WINDOW : undefined;
    return typeof w === 'number' && isFinite(w) && w > 0 ? w : 2.5;
  }

  const MANY_HANDS_ARMS = [1, 1, 2, 2, 3];
  function nextArmLevel(L) {
    const l = Math.max(1, Math.round(L || 1));
    for (let k = l + 1; k <= MANY_HANDS_ARMS.length; k++) if (MANY_HANDS_ARMS[k - 1] > MANY_HANDS_ARMS[Math.min(l, MANY_HANDS_ARMS.length) - 1]) return k;
    return 0;
  }

  const ULTIMATE_AT = 4;
  const STYLE_TIERS = [2, 4, 6];
  const MAX_RUN_SKILLS = 10;
