  const STYLE_BY_ID = {};
  for (const s of STYLES) STYLE_BY_ID[s.id] = s;
  const STYLE_OF = {};
  for (const s of STYLES) { s.skills.forEach((id) => { STYLE_OF[id] = s.id; }); STYLE_OF[s.ultimate] = s.id; }

  function styleTier(count) { let t = 0; for (const n of STYLE_TIERS) if (count >= n) t++; return t; }
  function styleBonusText(style, tier) {
    const s = STYLE_BY_ID[style];
    if (!s || !(tier >= 1)) return '';
    const v = s.bonus.at[Math.min(s.bonus.at.length, Math.floor(tier)) - 1];
    return '+' + P(v) + ' ' + s.bonus.mods.map((m) => m.label).join(' and ');
  }
  function styleBonus(style, count) {
    const s = STYLE_BY_ID[style];
    const tier = styleTier(count | 0);
    if (!s || !tier) return { tier: 0, value: 0, mods: [], text: '' };
    const value = s.bonus.at[tier - 1];
    return { tier, value, mods: s.bonus.mods.map((m) => ({ stat: m.stat, type: m.type, value, source: 'style:' + s.id })), text: styleBonusText(style, tier) };
  }

  function scaled(v, scales, active, sk) {
    if (!sk) return v;
    const o = Object.assign({}, v);
    const mul = (keys, k) => { if (!(k > 0) || !isFinite(k)) return; for (const key of keys || []) if (typeof o[key] === 'number') o[key] *= k; };
    mul(scales.dmg, sk.dmg);
    mul((scales.pot || []).filter((key) => key !== 'arms'), sk.pot);
    if (active && typeof o.cd === 'number' && o.cd > 0) mul(['cd'], sk.cd);
    return o;
  }

  function gainPart(g, a, b, st) {
    const [key, fmt, label, many] = g;
    const x = a[key], y = b[key];
    if (typeof y !== 'number' || typeof x !== 'number') return '';
    switch (fmt) {
      case 'dmg': case 'pct': { const d = Math.round(y * 100) - Math.round(x * 100); return d > 0 ? '+' + d + '% ' + (label || 'damage') : ''; }
      case 'pct1': { const d = Math.round(y * 10000) - Math.round(x * 10000); return d > 0 ? '+' + (d / 100) + '% ' + label : ''; }
      case 'cd': { const d = Math.round((x - y) * 100) / 100; return d > 0 ? S(d) + ' faster' : ''; }
      case 'sec': { const d = Math.round((y - x) * 100) / 100; return d > 0 ? '+' + S(d) + ' ' + label : ''; }
      case 'n': { const d = Math.round(y) - Math.round(x); return d > 0 ? '+' + plural(d, label, many) : ''; }
      case 'num': { const d = Math.round(y) - Math.round(x); return d > 0 ? '+' + d + ' ' + label : ''; }
      case 'nth': return Math.round(y) < Math.round(x) ? 'every ' + ORD(y) + ' stamp' : '';
      case 'def': { const k = biomeScale(st); const d = Math.round(y * k) - Math.round(x * k); return d > 0 ? '+' + N(d) + ' ' + W.skin() : ''; }
      case 'thorns': {
        const p = punchOf(st);
        if (p) { const d = Math.round(y * p) - Math.round(x * p); return d > 0 ? '+' + N(d) + ' damage back' : ''; }
        const d = Math.round(y * 100) - Math.round(x * 100);
        return d > 0 ? '+' + d + '% of a stamp back' : '';
      }
      case 'revive': return y > 0 && !(x > 0) ? 'revive once' : '';
      case 'done': return Math.round(y * 100) > Math.round(x * 100) ? 'from ' + (100 - Math.round(y * 100)) + '% done' : '';
      default: return '';
    }
  }

  function mk(spec) {
    const T = spec.T || {};
    const maxLevel = spec.maxLevel || 5;
    const tables = maxLevel > 1;
    const scales = { dmg: (spec.scales && spec.scales.dmg) || [], pot: (spec.scales && spec.scales.pot) || [] };
    const active = spec.kind === 'active';
    const vals = (L) => {
      const o = {};
      for (const k in T) o[k] = tables && Array.isArray(T[k]) ? at(T[k], L) : T[k];
      return o;
    };
    const style = STYLE_BY_ID[STYLE_OF[spec.id]];
    const lvl = (L) => Math.max(1, Math.min(maxLevel, Math.round(L || 1)));
    const def = {
      id: spec.id,
      name: spec.name,
      style: style.id,
      styleColor: style.color,
      ultimate: !!spec.ultimate,
      starter: !spec.ultimate && style.starters.indexOf(spec.id) >= 0,
      order: spec.ultimate ? style.skills.length : style.skills.indexOf(spec.id),
      kind: spec.kind,
      maxLevel,
      color: spec.color,
      tags: spec.tags || [],
      glyph: spec.glyph || spec.id,
      shortDesc: spec.shortDesc,
      blurb: spec.shortDesc,
      vals,
      scales,
      desc: (L, st, sk) => {
        try { return spec.desc(scaled(vals(lvl(L)), scales, active, sk), lvl(L), st); } catch (e) { return spec.shortDesc || spec.name; }
      },
      gain: (L, st, sk) => {
        const l = lvl(L);
        if (l <= 1) return '';
        try {
          const a = scaled(vals(l - 1), scales, active, sk), b = scaled(vals(l), scales, active, sk);
          const parts = (spec.gainFirst ? spec.gainFirst(a, b) : []).concat((spec.gain || []).map((g) => gainPart(g, a, b, st))).filter(Boolean);
          return parts.slice(0, 3).join(', ') || 'stronger';
        } catch (e) { return 'stronger'; }
      },
    };
    if (spec.mods) def.mods = (L, st) => { try { return spec.mods(vals(lvl(L)), lvl(L), st) || []; } catch (e) { return []; } };
    return def;
  }

