  KK.Team = Team;

  const AGENT_NAMES = { duck: 'Quick', claude: 'Claude', codex: 'Codex', kiro: 'Kiro' };
  const agentName = (id) => { const g = G(); return (g && g.agentNames && typeof g.agentNames[id] === 'string' && g.agentNames[id]) || AGENT_NAMES[id] || id; };
  const AGENT_LEVEL_COST = { base: 80, growth: 1.12 };
  const AGENTS = [
    { id: 'duck', name: agentName('duck'), starter: true, color: '#ffd23f', face: 'quick', glyph: 'Q', job: 'quick', every: 8, verb: 'answers the easy asks',
      unlock: null, base: { count: 2, upTo: 6, heal: 0.02 }, desc: 'Answers the easy asks: the smallest requests on screen are resolved at once, and you get a little Energy back.' },
    { id: 'claude', name: agentName('claude'), color: '#7cc4ff', face: 'thinker', glyph: '?', job: 'precise', every: 10, verb: 'thinks it through',
      unlock: { awards: 5 }, base: { share: 16, chain: 2, chainDamage: 0.6, hop: 220 }, desc: 'Thinks before it stamps: one big precise stamp on the toughest request.' },
    { id: 'codex', name: agentName('codex'), color: '#ff9ec4', face: 'speedy', glyph: '>', job: 'burst', every: 6, verb: 'ships fast',
      unlock: { awards: 5 }, base: { share: 1.35, hits: 3, targets: 5 }, desc: 'Ships fast: a burst of quick stamps on many requests.' },
    { id: 'kiro', name: agentName('kiro'), color: '#b8e986', face: 'planner', glyph: '#', job: 'spec', every: 12, verb: 'spec first',
      unlock: { awards: 8 }, base: { cdr: 0.2, dur: 5, prog: 0.15, cap: 5, targets: 5 }, desc: 'Writes the spec first: your skills recharge faster and the nearest tasks move along.' },
  ];
  const AG_BY_ID = {};
