    if (g.job === 'precise') { s.share = b.share * dm; s.chain = b.chain; s.chainDamage = b.chainDamage; s.hop = b.hop; }
    if (g.job === 'burst') { s.share = b.share * dm; s.hits = b.hits; s.targets = b.targets; }
    if (g.job === 'spec') { s.cdr = Math.min(AGENT_CDR_MAX, b.cdr * sm); s.dur = b.dur; s.prog = b.prog * sm; s.cap = b.cap * dm; s.targets = b.targets; }
