    burrow: {
      name: 'Pop-Up Review', w: 1.5, cd: 6,
      start(st, e, P) {
        setState(e, 'burrow');
        P.phase = 'dig'; P.ph0 = 0;
        P.count = e.ai.enraged ? 2 : 1;
        P.dur = 99;
        KK.fx('burst', { x: e.x, y: e.y, color: '#e8c27a', count: 16, speed: 200, size: 7, life: 0.6, gravity: 300 });
        KK.sfx('boss_cast', { pitch: 0.6 });
      },
      tick(st, e, dt, P) {
        const h = st.hero;
        if (P.phase === 'dig' || P.phase === 'travel') e.untargetableT = Math.max(e.untargetableT || 0, 0.12);
        const since = P.t - P.ph0;
        if (P.phase === 'dig') {
          if (since >= 0.45) {
            P.phase = 'travel'; P.ph0 = P.t;
            const a0 = hAng(st, e) + Math.PI + st.rng.range(-0.5, 0.5);
            const want = e.r + h.r + 46;
            const p = cp(h.x + Math.cos(a0) * want, h.y + Math.sin(a0) * want, e.r + 4);
            if (B.bossHeadLine) p.y = Math.max(p.y, B.bossHeadLine(e, 8));
            P.tx = p.x; P.ty = p.y;
          }
          return;
        }
        if (P.phase === 'travel') {
          const tx = P.tx, ty = P.ty;
          const d = Math.hypot(tx - e.x, ty - e.y);
          if (d > 10 && since < 1.4) {
            const a = Math.atan2(ty - e.y, tx - e.x);
            const step = Math.min(d, 340 * dt);
            e.x += Math.cos(a) * step; e.y += Math.sin(a) * step;
            B.clampToArena(e);
            e.facing = a;
            if (Math.random() < 0.25) KK.fx('dust', { x: e.x, y: e.y, angle: a + Math.PI });
          } else {
            P.phase = 'rise'; P.ph0 = P.t;
            e.untargetableT = 0;
            e.facing = hAng(st, e);
            P.tell = chargeUp(st, e, P, T(e, 0.95), { big: true });
            KK.fx('burst', { x: e.x, y: e.y, color: '#e8c27a', count: 22, speed: 300, size: 8, life: 0.7, gravity: 500 });
          }
          return;
        }
        if (P.phase === 'rise') {
          if (since >= P.tell) {
            e.ai.charge = null;
            if (hDist(st, e) <= e.r + h.r + 120) hitB(st, e, 1.25, 'melee', P.tell);
            impact(st, e.x, e.y, e.r + 40, '#f3d89c', 12);
            setState(e, 'attack');
            P.phase = 'up'; P.ph0 = P.t;
            P.count--;
          }
          return;
        }
        if (P.phase === 'up') { if (since >= 0.4) { setState(e, 'recover'); P.phase = 'rest'; P.ph0 = P.t; } return; }
        if (P.phase === 'rest') {
          if (since >= (P.count > 0 ? 0.5 : 0.95)) {
            if (P.count > 0 && h.alive) { setState(e, 'burrow'); P.phase = 'dig'; P.ph0 = P.t; }
            else P.done = true;
          }
        }
      },
      end(st, e) { e.untargetableT = 0; },
    },
