  function nearestTasks(st, x, y, maxR, n) {
    const out = [];
    const m2 = maxR * maxR;
    const list = st.enemies;
    for (let i = 0; i < list.length; i++) {
      const e = list[i];
      if (!targetable(e) || !e.entered) continue;
      const d = U.dist2(x, y, e.x, e.y);
      if (d > m2) continue;
      let k = out.length;
      while (k > 0 && out[k - 1].d > d) k--;
      if (k >= n) continue;
      out.splice(k, 0, { e, d });
      if (out.length > n) out.length = n;
    }
    for (let i = 0; i < out.length; i++) out[i] = out[i].e;
    return out;
  }
