    const text = String(d.text || 'POW!').slice(0, 14);
    const b = heroBody();
    if (b.ok) {
      const dx = x - b.x, dy = y - b.y, dd = Math.hypot(dx, dy);
      if (dd < POP_CLEAR) { if (dd < 1) { y = b.y - POP_CLEAR; } else { x = b.x + dx / dd * POP_CLEAR; y = b.y + dy / dd * POP_CLEAR; } }
    }
    const A = KK.Battle && KK.Battle.ARENA;
    if (A) { x = U.clamp(x, A.left + 70, A.right - 70); y = U.clamp(y, A.top + 36, A.bottom - 30); }
    let q;
    if (nPops < POP_CAP) q = pops[nPops++];
