  const SCALLOP = (x, y, r, n, k) => (ctx) => {
    const bump = 1 + (k || 0.16);
    for (let i = 0; i <= n; i++) {
      const a = (i / n) * TAU - PI / 2, px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
      if (i === 0) { ctx.moveTo(px, py); continue; }
      const m = ((i - 0.5) / n) * TAU - PI / 2;
      ctx.quadraticCurveTo(x + Math.cos(m) * r * bump, y + Math.sin(m) * r * bump, px, py);
    }
    ctx.closePath();
  };
