    g.push(x, y, s, 0);
    g.part((ctx) => { ctx.moveTo(-36, -8); ctx.lineTo(-30, -40); ctx.quadraticCurveTo(0, -50, 30, -40); ctx.lineTo(36, -8); ctx.closePath(); }, dk(P[0], 0.25), { g: [-46, -8], hl: [-14, -36, 12, 3] });
