      const all = (Floor.list || []).length;
      const M = Floor.more;
      if (M && all > 1) { M.textContent = '+' + (all - 1) + ' more'; M.classList.remove('hidden'); Floor.moreText = null; }
      const R = Floor.room(phone);
      if (!R || !(R.w > 0)) return cs.length;
      const wOf = (n) => { const b = n.getBoundingClientRect ? n.getBoundingClientRect() : null; return (b && b.width > 0 ? b.width : n.offsetWidth) || 0; };
      const ws = cs.map((c) => wOf(c.el));
      if (!ws.some((w) => w > 0)) return cs.length;
      const moreW = M && all > 1 ? wOf(M) + Math.max(0, R.tailGap - R.gap) : 0;
      const n = Floor.pack(ws, R.w, R.gap, R.rows, moreW, all > cs.length);
      for (let i = n; i < cs.length; i++) cs[i].el.classList.add('hidden');
      return n;
