    const waiting = phone && !!s && (s.giantFell | 0) > 0 && (s.giantFell | 0) === (s.wave | 0) && !s.transition && s.phase !== 'over' && !(HUD.wonFor > 0);
    if (!waiting) { HUD.keptFor = 0; return false; }
