    copyText: () => (onTouch() ? 'Tap and hold the text below to copy it.' : 'Select the text below and copy it (Ctrl+C, or Cmd+C on a Mac).'),
    copyCode: () => (onTouch() ? 'Tap and hold the code below to copy it.' : 'Select the code below and copy it (Ctrl+C, or Cmd+C on a Mac).'),
    reopen: () => (onTouch() ? 'close ' + gameName() + ' and open it again' : 'quit ' + gameName() + ' and open it again'),
