      const free = !!opts.anyStart || !!(KK.Debug && KK.Debug.enabled);
      const checkpoints = free ? undefined : (j && Array.isArray(j.checkpoints) ? j.checkpoints : [1]);
      let metaStats = null, bonuses = {};
