      if (bonuses.startShield && KK.Battle.state) KK.Battle.state.hero.shield = bonuses.startShield;
      Game.mode = 'battle';
      KK.Loop.speed = settings.gameSpeed || 1;
      Game._show('battle');
      const biome = KK.Battle.state.biome;
